            for(const key in bty.portraits) {
              portraitsHTML += `<div class="comparison-item">
                                 <div class="title">${portraitMap[key]}</div>
                                 <div class="content">${bty.portraits[key].replace(/\n/g, '<br>')}</div>
                               </div>`;
            }
            let recordsHTML = bty.records.map((r, i) => `<div class="review"><strong>【行乐记之${i+1}】</strong><br>${r.replace(/\n/g, '<br>')}</div>`).join('');

            contentArea.innerHTML = `
                <div class="detail-view">
                    <button class="back-button" onclick="window.renderBeauties(${houseIndex})"><i class="fa-solid fa-arrow-left"></i> 返回上一页</button>
