                        <div class="card-tags">${bty.tags.map(t => `<span class="tag">${t}</span>`).join('')}</div>
                    </div>
                    <div class="detail-section">
                        <h4 class="section-title">采花前后六景</h4>
                        <div class="comparison-gallery">${portraitsHTML}</div>
                    </div>
