                        <div class="reviews">${recordsHTML}</div>
                    </div>
                    <button class="order-button">指定此姝为下一目标</button>
                </div>
            `;

            contentArea.querySelector('.order-button').onclick = () => {
                const remarks = prompt(`为采花贼们下达关于“${bty.name}”的密令（可留空）：`, '');
                if (remarks === null) return;
