                const beautyRegex = /\[尤物\]([\s\S]*?)\[\/尤物\]/g;
                let beautyMatch;
                while((beautyMatch = beautyRegex.exec(houseContent)) !== null) {
                    const btyContent = `\n${beautyMatch[1]}`;
                    const bty = {};
                    bty.name = btyContent.match(/\nname: (.*)/)?.[1].trim() || '无名尤物';
                    bty.title = btyContent.match(/\ntitle: (.*)/)?.[1].trim() || '芳名未知';
                    bty.rating = parseFloat(btyContent.match(/\nrating: (.*)/)?.[1] || 0);
                    bty.description = btyContent.match(/\ndescription: ([\s\S]*?)(?=\ntags:)/)?.[1].trim() || '';
                    bty.tags = parseBlockList(btyContent, 'tags');

                    bty.portraits = {};
                    const portraits = ['face', 'bosom', 'private_part', 'feet', 'buttocks', 'full_body'];
                    portraits.forEach(p => {
                        const regex = new RegExp(`\\n${p}: ([\\s\\S]*?)(?=\\n(face|bosom|private_part|feet|buttocks|full_body|records):)`);
                        const match = btyContent.match(regex);
                        if(match) bty.portraits[p] = match[1].trim();
                    });

                    bty.records = [];
                    for(let i=1; i<=5; i++) {
                        const recRegex = new RegExp(`\\nrecord${i}: "([\\s\\S]*?)"`);
                        const recMatch = btyContent.match(recRegex);
                        if(recMatch) bty.records.push(recMatch[1].trim());
                    }
                    house.beauties.push(bty);
                }
                appData.flowerHouses.push(house);
            }
        }

        function parseBlockList(content, key) {
            const lines = content.split('\n'); const result = []; let inList = false;
            for (const line of lines) {
                if (line.trim().startsWith(key + ':')) { inList = true; continue; }
                if (inList) {
                    const trimmedLine = line.trim();
                    if (trimmedLine.startsWith('- ')) { result.push(trimmedLine.substring(2)); }
                     else if (trimmedLine !== '' && /^\w+:/.test(trimmedLine)) { inList = false; }
                }
            }
            return result;
        }

